{
  "tasks": [
    {
      "task_id": "T01",
      "title": "上海与杭州薪资元平均值对比及排名",
      "business_question": "只看上海与杭州，计算各城市的薪资元平均值，并按该平均值降序排名。",
      "priority": "P0",
      "priority_reason": "删除后无法回答核心比较需求(C01)，且缺失关键指标计算(C03)和排序约束(C04)。必须严格遵循筛选条件(C02)。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0001",
                "operator": "in",
                "value": [
                  "上海",
                  "杭州"
                ]
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "avg",
                "field": "field_0004",
                "alias": "salary_avg"
              }
            ],
            "dimensions": [
              "field_0001"
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "sort",
          "params": {
            "field": "salary_avg",
            "direction": "desc"
          }
        }
      ]
    }
  ]
}
